/**
 * Runtime configuration (Lambda environment) and the engagement secret.
 *
 * The secret (merch-os/<env>/engagement) holds JSON { "tokenSecret": "..." },
 * generated by CloudFormation. It signs the review and unsubscribe links in
 * emails. Values never go in env vars.
 */

import { GetSecretValueCommand, SecretsManagerClient } from '@aws-sdk/client-secrets-manager';

function required(name: string): string {
  const value = process.env[name];
  if (!value) throw new Error(`${name} is not configured`);
  return value;
}

const trimSlash = (s: string): string => s.replace(/\/$/, '');

export const config = {
  get table(): string {
    return required('ENGAGEMENT_TABLE');
  },
  get secretArn(): string {
    return required('ENGAGEMENT_SECRET_ARN');
  },
  /** Lifecycle email sender (every email except Cognito security codes). */
  get fromEmail(): string {
    return process.env['FROM_EMAIL'] || 'MerchOS <info@merchos.co.za>';
  },
  /** Replies go to the support mailbox; low ratings alert it too. */
  get supportEmail(): string {
    return process.env['SUPPORT_EMAIL'] || 'info@merchos.co.za';
  },
  /** Seller site (links in emails). */
  get siteUrl(): string {
    return trimSlash(process.env['SITE_URL'] || 'https://merchos.co.za');
  },
  /** This service's own HTTP API (one-click unsubscribe header). */
  get apiUrl(): string {
    return trimSlash(required('ENGAGEMENT_API_URL'));
  },
  get adminBaseUrl(): string {
    return trimSlash(process.env['ADMIN_BASE_URL'] || 'https://admin.merchos.co.za');
  },
  get userPoolId(): string {
    return required('USER_POOL_ID');
  },
  get tenantsTable(): string {
    return required('TENANTS_TABLE');
  },
  get productsTable(): string {
    return required('PRODUCTS_TABLE');
  },
  get sellerOrigins(): string[] {
    return (process.env['SELLER_ORIGINS'] ?? '').split(',').filter(Boolean);
  },
  get scheduledFunctionArn(): string {
    return required('SCHEDULED_FUNCTION_ARN');
  },
  get schedulerRoleArn(): string {
    return required('SCHEDULER_ROLE_ARN');
  },
  get scheduleGroup(): string {
    return required('SCHEDULE_GROUP');
  },
};

let secretsClient: SecretsManagerClient | undefined;
let cachedSecret: string | undefined;

export async function getTokenSecret(): Promise<string> {
  if (cachedSecret) return cachedSecret;
  secretsClient ??= new SecretsManagerClient({});
  const out = await secretsClient.send(new GetSecretValueCommand({ SecretId: config.secretArn }));
  const parsed = JSON.parse(out.SecretString ?? '{}') as { tokenSecret?: string };
  if (!parsed.tokenSecret) throw new Error('Engagement secret has no tokenSecret');
  cachedSecret = parsed.tokenSecret;
  return cachedSecret;
}

/** @internal tests only */
export function _setTokenSecret(value: string | undefined): void {
  cachedSecret = value;
}
